import pytest

from bedrock_protocol import v2168, v2193

# generated by gophertunnel 218ac3f:
# packet.Disconnect{Reason: 147, HideDisconnectionScreen: false, Message: "bye", FilteredMessage: "b**"}
WITH_MESSAGES = bytes.fromhex("a602000362796503622a2a")

# generated by gophertunnel 218ac3f:
# packet.Disconnect{Reason: 147, HideDisconnectionScreen: true}
WITHOUT_MESSAGES = bytes.fromhex("a60201")

GOLDENS = [
    pytest.param(
        v2168.DisconnectPacket(
            reason=v2168.DisconnectFailReason.EDITOR_NOT_ALLOWED,
            messages=v2168.DisconnectPacketMessages(message="bye", filtered_message="b**"),
        ),
        WITH_MESSAGES,
        id="v2168-with-messages",
    ),
    pytest.param(
        v2168.DisconnectPacket(reason=v2168.DisconnectFailReason.EDITOR_NOT_ALLOWED, messages=None),
        WITHOUT_MESSAGES,
        id="v2168-without-messages",
    ),
    pytest.param(
        v2193.DisconnectPacket(
            reason=v2193.DisconnectFailReason.EDITOR_NOT_ALLOWED,
            messages=v2193.DisconnectPacketMessages(message="bye", filtered_message="b**"),
        ),
        WITH_MESSAGES,
        id="v2193-with-messages",
    ),
    pytest.param(
        v2193.DisconnectPacket(reason=v2193.DisconnectFailReason.EDITOR_NOT_ALLOWED, messages=None),
        WITHOUT_MESSAGES,
        id="v2193-without-messages",
    ),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_disconnect_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_disconnect_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("member", "value"),
    [
        pytest.param(v2168.DisconnectFailReason.EDITOR_NOT_ALLOWED, 147, id="v2168-editor-not-allowed"),
        pytest.param(v2193.DisconnectFailReason.MISSING_STRUCTURE_DATA, 148, id="v2193-missing-structure-data"),
        pytest.param(v2193.DisconnectFailReason.UNSUPPORTED_TRANSPORT, 149, id="v2193-unsupported-transport"),
    ],
)
def test_2193_appends_two_fail_reasons_after_editor_not_allowed(member, value):
    assert member == value


def test_a_fail_reason_2193_added_round_trips():
    packet = v2193.DisconnectPacket(reason=v2193.DisconnectFailReason.MISSING_STRUCTURE_DATA, messages=None)
    assert v2193.DisconnectPacket.from_bytes(bytes(packet)) == packet
